import numpy as np, pandas as pd
from scipy.optimize import minimize
df = pd.read_parquet(r'<workspace>\equation.parquet')
data = df.iloc[0]['training_set'].tolist()
Y = np.array([r[0] for r in data]); X = np.array([r[1:] for r in data]); t=X[:,0]; A=X[:,1]
def fit(f):
    r=minimize(lambda p: np.mean((f(t,A,p)-Y)**2), [1.0]*10, method='BFGS')
    return r.fun, r.x
forms = {
 'two_exp': lambda t,A,p: p[0]*np.exp(-p[1]*t)*A + p[2]*np.exp(-p[3]*t)*A + p[4]*t + p[5]*A + p[6],
 'rational': lambda t,A,p: p[0]*t*A/(1+p[1]*t) + p[2]*np.exp(-p[3]*t)*A + p[4]*t + p[5]*A + p[6],
 'logistic': lambda t,A,p: p[0]*A/(1+np.exp(-p[1]*(t-p[2]))) + p[3]*np.exp(-p[4]*t)*A + p[5]*t + p[6]*A + p[7],
 'mix': lambda t,A,p: p[0]*np.exp(-p[1]*t)*A**2 + p[2]*t*A**2 + p[3]*t*A/(1+p[4]*t) + p[5]*t + p[6]*A + p[7],
 'mix2': lambda t,A,p: p[0]*np.exp(-p[1]*t)*A + p[2]*t*A**2 + p[3]*t*A/(1+p[4]*t) + p[5]*t + p[6]*A + p[7],
}
for k,f in forms.items():
    try:
        l,x=fit(f); print(k, l)
    except Exception as e:
        print(k,'ERR',e)

import numpy as np, pandas as pd
from scipy.optimize import minimize
df = pd.read_parquet(r'<workspace>\equation.parquet')
data = df.iloc[0]['training_set'].tolist()
Y = np.array([r[0] for r in data]); X = np.array([r[1:] for r in data]); t=X[:,0]; A=X[:,1]
def fit(f):
    best=(1e9,None)
    for s in range(3):
        r=np.random.RandomState(s)
        r=minimize(lambda p: np.mean((f(t,A,p)-Y)**2), np.abs(np.random.randn(10))+0.5, method='BFGS', options={'maxiter':2000,'gtol':1e-12})
        if r.fun<best[0]: best=(r.fun, r.x)
    return best
forms = {
 'rat2exp': lambda t,A,p: p[0]*t*A/(1+p[1]*t) + p[2]*np.exp(-p[3]*t)*A + p[4]*np.exp(-p[5]*t)*A + p[6]*t + p[7]*A + p[8],
 'ratA': lambda t,A,p: p[0]*t*A/(1+p[1]*t) + p[2]*A/(1+p[3]*A) + p[4]*np.exp(-p[5]*t)*A + p[6]*t + p[7]*A + p[8],
 'rational': lambda t,A,p: p[0]*t*A/(1+p[1]*t) + p[2]*np.exp(-p[3]*t)*A + p[4]*t + p[5]*A + p[6],
 'ratiopps': lambda t,A,p: p[0]*t*A/(1+p[1]*t+p[2]*A) + p[3]*np.exp(-p[4]*t)*A + p[5]*t + p[6]*A + p[7],
}
for k,f in forms.items():
    l,x=fit(f); print(k, l)
